import networkx as nx, random, itertools, sys, math
sys.path.insert(0,'/workspace/submission')
from pipeline_allgather import BranchingGenerator, OptimalBranchingsAlgo, flat_edge_map

SOURCE='SOURCE'

def remove_switches(topo, compute_nodes, root_caps):
